INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('(the) chances are (that)', '아마도 ~일 것이다', '[{"pos": "phr.", "ko": "아마도 ~일 것이다"}, {"pos": "phr.", "ko": "~할 가능성이 높다"}]'::jsonb, 'The chances are that it will rain tomorrow, so bring your umbrella.', '내일은 비가 올 것 같으니 우산을 챙겨라.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abandon', '버리다', '[{"pos": "v.", "ko": "(사람·장소를) 버리다"}, {"pos": "v.", "ko": "(계획·신념을) 포기하다"}]'::jsonb, 'The hikers had to abandon their campsite due to the sudden storm.', '등산객들은 갑작스러운 폭풍 때문에 야영지를 버려야 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ability', '능력', '[{"pos": "n.", "ko": "능력, 할 수 있음"}]'::jsonb, 'Her ability to solve complex problems impressed her teachers.', '그녀가 복잡한 문제를 푸는 능력은 선생님들에게 깊은 인상을 주었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('aboard', '탑승하여', '[{"pos": "ad.", "ko": "(배·비행기 등에) 탑승하여"}, {"pos": "prep.", "ko": "~에 탑승한"}]'::jsonb, 'All passengers must be aboard the plane before it departs.', '모든 승객은 비행기가 출발하기 전에 탑승해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('absolute', '완전한', '[{"pos": "a.", "ko": "완전한, 전적인"}, {"pos": "a.", "ko": "절대적인"}, {"pos": "a.", "ko": "확실한, 틀림없는"}]'::jsonb, 'The experiment requires absolute silence in the laboratory.', '그 실험은 실험실에서 완전한 정적이 필요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('absorb', '흡수하다', '[{"pos": "v.", "ko": "(액체·기체를) 흡수하다"}, {"pos": "v.", "ko": "(정보·지식을) 받아들이다"}, {"pos": "v.", "ko": "열중하게 하다"}]'::jsonb, 'A sponge can absorb a large amount of water quickly.', '스펀지는 많은 양의 물을 빠르게 흡수할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('abstract', '추상적인', '[{"pos": "a.", "ko": "추상적인"}, {"pos": "a.", "ko": "이론적인"}, {"pos": "v.", "ko": "추출하다"}, {"pos": "v.", "ko": "요약하다"}, {"pos": "n.", "ko": "추상"}, {"pos": "n.", "ko": "요약, 발췌"}]'::jsonb, 'The artist is famous for his abstract paintings full of colors and shapes.', '그 화가는 색과 형태가 가득한 추상화로 유명하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('absurd', '터무니없는', '[{"pos": "a.", "ko": "터무니없는, 어리석은"}, {"pos": "a.", "ko": "불합리한"}]'::jsonb, 'It would be absurd to believe such an obvious lie.', '그렇게 뻔한 거짓말을 믿는 것은 터무니없다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('academic', '학업의', '[{"pos": "a.", "ko": "학업의, 학교의"}, {"pos": "a.", "ko": "학문적인, 이론적인"}, {"pos": "n.", "ko": "학자"}]'::jsonb, 'Many students feel pressure to achieve high academic standards.', '많은 학생들이 높은 학업 기준을 맞추기 위해 압박을 느낀다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('accelerate', '가속하다', '[{"pos": "v.", "ko": "속도를 높이다, 가속하다"}, {"pos": "v.", "ko": "(일의 진행을) 촉진하다"}]'::jsonb, 'The car began to accelerate as it entered the highway.', '차가 고속도로에 진입하면서 속도를 내기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('accept', '받아들이다', '[{"pos": "v.", "ko": "받아들이다, 수락하다"}, {"pos": "v.", "ko": "(사실·설명 등을) 인정하다, 믿다"}, {"pos": "v.", "ko": "(단체에) 받아들이다, 가입시키다"}]'::jsonb, 'She decided to accept the invitation to the ceremony.', '그녀는 행사 초대를 받아들이기로 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('access', '접근', '[{"pos": "n.", "ko": "접근, 이용"}, {"pos": "n.", "ko": "진입 방법, 통로"}, {"pos": "v.", "ko": "(정보 등에) 접근하다, 입수하다"}]'::jsonb, 'Only authorized personnel have access to this laboratory.', '이 실험실에는 허가받은 사람만 접근할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('accident', '사고', '[{"pos": "n.", "ko": "사고, 재난"}, {"pos": "n.", "ko": "우연한 일, 뜻밖의 사건"}]'::jsonb, 'The accident on the highway caused a long traffic jam.', '고속도로에서 발생한 사고로 긴 교통 체증이 생겼다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('accompany', '동행하다', '[{"pos": "v.", "ko": "동행하다, 함께 가다"}, {"pos": "v.", "ko": "(현상 등이) 수반하다, 함께 나타나다"}, {"pos": "v.", "ko": "(음악을) 반주하다"}]'::jsonb, 'Parents are required to accompany their children on the field trip.', '학부모는 소풍에 자녀와 동행해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('accomplish', '이루다', '[{"pos": "v.", "ko": "이루다, 성취하다, 완수하다"}]'::jsonb, 'She worked hard to accomplish her goals before graduation.', '그녀는 졸업 전에 목표를 이루기 위해 열심히 노력했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('according to', '~에 따르면', '[{"pos": "prep.", "ko": "~에 따르면, ~에 의하면"}]'::jsonb, 'According to the report, the economy is improving steadily.', '보고서에 따르면 경제가 꾸준히 회복되고 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('account', '계좌', '[{"pos": "n.", "ko": "계좌"}, {"pos": "n.", "ko": "설명, 보고"}, {"pos": "n.", "ko": "이유, 원인"}]'::jsonb, 'She opened a new bank account to save money for college.', '그녀는 대학 등록금을 모으기 위해 새 은행 계좌를 만들었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('accumulate', '모으다', '[{"pos": "v.", "ko": "모으다, 축적하다"}, {"pos": "v.", "ko": "쌓이다, 누적되다"}]'::jsonb, 'Over the years, he managed to accumulate a lot of experience.', '그는 오랜 시간 동안 많은 경험을 쌓았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('accurate', '정확한', '[{"pos": "a.", "ko": "정확한, 정밀한"}]'::jsonb, 'His description of the scene was accurate and detailed.', '그의 현장 묘사는 정확하고 자세했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('accuse', '고발하다', '[{"pos": "v.", "ko": "고발하다, 기소하다"}, {"pos": "v.", "ko": "비난하다"}]'::jsonb, 'The police accused him of stealing the bicycle.', '경찰은 그를 자전거를 훔친 혐의로 고발했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('achieve', '이루다', '[{"pos": "v.", "ko": "이루다, 성취하다"}, {"pos": "v.", "ko": "달성하다"}]'::jsonb, 'He worked hard to achieve his dream of becoming a doctor.', '그는 의사가 되겠다는 꿈을 이루기 위해 열심히 노력했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('acid', '산', '[{"pos": "n.", "ko": "산(酸)"}, {"pos": "a.", "ko": "신, 신맛의"}]'::jsonb, 'Lemon juice contains acid that gives it a sour taste.', '레몬즙에는 신맛을 내는 산이 들어 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('acknowledge', '인정하다', '[{"pos": "v.", "ko": "인정하다"}, {"pos": "v.", "ko": "감사하다, 사례하다"}, {"pos": "v.", "ko": "받았음을 알리다"}]'::jsonb, 'He refused to acknowledge his mistake in the report.', '그는 보고서에서 자신의 실수를 인정하지 않았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('acquire', '획득하다', '[{"pos": "v.", "ko": "획득하다, 얻다"}, {"pos": "v.", "ko": "습득하다, 배우다"}]'::jsonb, 'She hopes to acquire new skills during her internship.', '그녀는 인턴십 동안 새로운 기술을 얻기를 바란다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('activate', '작동시키다', '[{"pos": "v.", "ko": "작동시키다, 활성화하다"}, {"pos": "v.", "ko": "활동적으로 만들다"}]'::jsonb, 'You need to activate your account before using the service.', '서비스를 이용하려면 계정을 먼저 작동시켜야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
