INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('anxiety', '걱정', '[{"pos": "n.", "ko": "걱정, 불안"}, {"pos": "n.", "ko": "갈망, 열망"}]'::jsonb, 'Many students feel anxiety before taking an important exam.', '많은 학생들이 중요한 시험을 앞두고 걱정을 느낀다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
