INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('concern', '걱정', '[{"pos": "n.", "ko": "걱정, 염려"}, {"pos": "n.", "ko": "관심사"}, {"pos": "v.", "ko": "걱정하다, 염려하다"}, {"pos": "v.", "ko": "관계하다, 관련되다"}]'::jsonb, 'Environmental pollution is a major concern for many people today.', '환경 오염은 오늘날 많은 사람들의 큰 걱정거리다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conclude', '결론을 내리다', '[{"pos": "v.", "ko": "결론을 내리다"}, {"pos": "v.", "ko": "끝내다, 마치다"}, {"pos": "v.", "ko": "(협정 등을) 체결하다"}]'::jsonb, 'After reviewing all the evidence, the jury concluded that the suspect was innocent.', '모든 증거를 검토한 후, 배심원단은 용의자가 무죄라고 결론지었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('concrete', '구체적인', '[{"pos": "a.", "ko": "구체적인, 명확한"}, {"pos": "n.", "ko": "콘크리트"}, {"pos": "a.", "ko": "콘크리트로 만든"}]'::jsonb, 'The teacher asked for concrete examples to support each student''s argument.', '선생님은 각 학생의 주장을 뒷받침할 구체적인 예시를 요구했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('condition', '상태', '[{"pos": "n.", "ko": "상태, 환경"}, {"pos": "n.", "ko": "조건"}, {"pos": "v.", "ko": "길들이다, 영향을 주다"}]'::jsonb, 'The car was sold in excellent condition after being carefully maintained.', '그 자동차는 잘 관리되어 아주 좋은 상태로 팔렸다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conduct', '수행하다', '[{"pos": "v.", "ko": "수행하다, 실시하다"}, {"pos": "v.", "ko": "이끌다, 안내하다"}, {"pos": "n.", "ko": "행동, 처신"}]'::jsonb, 'The scientists conducted several experiments to test their new theory.', '과학자들은 새로운 이론을 검증하기 위해 여러 실험을 수행했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('confident', '자신 있는', '[{"pos": "a.", "ko": "자신 있는, 확신하는"}, {"pos": "a.", "ko": "자신만만한"}]'::jsonb, 'He felt confident about his answers after studying hard for the test.', '그는 시험을 열심히 공부한 후 자신의 답에 자신이 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('confirm', '확인하다', '[{"pos": "v.", "ko": "확인하다, 확정하다"}, {"pos": "v.", "ko": "사실임을 보여주다"}, {"pos": "v.", "ko": "인정하다"}]'::jsonb, 'Please confirm your reservation by replying to this email as soon as possible.', '이 이메일에 최대한 빨리 회신하여 예약을 확인해 주세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conflict', '갈등', '[{"pos": "n.", "ko": "의견이나 이익의 충돌, 갈등"}, {"pos": "n.", "ko": "싸움이나 분쟁"}, {"pos": "v.", "ko": "의견 등이 서로 맞지 않다, 충돌하다"}]'::jsonb, 'The conflict between the two groups lasted for several years.', '두 집단 사이의 갈등은 수년간 계속되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conform', '따르다', '[{"pos": "v.", "ko": "관습이나 규칙에 따르다, 순응하다"}, {"pos": "v.", "ko": "모양이나 성질이 일치하다"}]'::jsonb, 'Most students conform to the school''s dress code without complaint.', '대부분의 학생들은 학교 복장 규정을 별다른 불만 없이 따른다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('confront', '직면하다', '[{"pos": "v.", "ko": "문제나 어려움에 직면하다"}, {"pos": "v.", "ko": "누군가에게 맞서다, 대면하다"}]'::jsonb, 'We must confront our fears to overcome them.', '우리는 두려움을 극복하기 위해 그것과 직면해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('confuse', '혼란스럽게 하다', '[{"pos": "v.", "ko": "혼란스럽게 하다, 헷갈리게 하다"}, {"pos": "v.", "ko": "서로 혼동하다"}]'::jsonb, 'The complicated instructions confused many students.', '복잡한 설명이 많은 학생들을 혼란스럽게 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('connect', '연결하다', '[{"pos": "v.", "ko": "서로 연결하다, 잇다"}, {"pos": "v.", "ko": "관련짓다, 연관시키다"}, {"pos": "v.", "ko": "인터넷이나 네트워크에 접속하다"}]'::jsonb, 'Please connect the printer to your computer before installing the software.', '소프트웨어를 설치하기 전에 프린터를 컴퓨터에 연결하세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conquer', '정복하다', '[{"pos": "v.", "ko": "정복하다, 점령하다"}, {"pos": "v.", "ko": "상대나 적을 이기다"}, {"pos": "v.", "ko": "어려움이나 두려움을 극복하다"}]'::jsonb, 'The army was able to conquer the region after months of fighting.', '군대는 몇 달간의 전투 끝에 그 지역을 정복할 수 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conscience', '양심', '[{"pos": "n.", "ko": "양심, 옳고 그름을 판단하는 마음"}, {"pos": "n.", "ko": "도덕심, 도덕적 의식"}]'::jsonb, 'Her conscience would not allow her to lie to her friend.', '그녀는 양심 때문에 친구에게 거짓말을 할 수 없었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conscious', '의식하는', '[{"pos": "a.", "ko": "의식하고 있는, 자각하는"}, {"pos": "a.", "ko": "의식이 있는, 깨어 있는"}, {"pos": "a.", "ko": "의도적인, 일부러 하는"}]'::jsonb, 'She was conscious of the people watching her during the performance.', '그녀는 공연 중에 사람들이 자신을 보고 있다는 것을 의식했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('consequence', '결과', '[{"pos": "n.", "ko": "결과, 어떤 일의 끝"}, {"pos": "n.", "ko": "영향, 파급 효과"}, {"pos": "n.", "ko": "중요성, 의미"}]'::jsonb, 'One consequence of pollution is the destruction of marine life.', '오염의 한 결과는 해양 생물의 파괴이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conservative', '보수적인', '[{"pos": "a.", "ko": "보수적인, 전통을 중시하는"}]'::jsonb, 'His parents have conservative views about education.', '그의 부모님은 교육에 대해 보수적인 견해를 가지고 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('conserve', '보존하다', '[{"pos": "v.", "ko": "보존하다, 보호하다"}, {"pos": "v.", "ko": "절약하다, 아껴 쓰다"}]'::jsonb, 'We must conserve water to prevent shortages in the future.', '미래의 부족을 막기 위해 우리는 물을 보존해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
