INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('context', '문맥', '[{"pos": "n.", "ko": "문맥, 전후 관계"}, {"pos": "n.", "ko": "배경, 정황"}]'::jsonb, 'You need to understand the context to interpret this sentence correctly.', '이 문장을 올바르게 해석하려면 문맥을 이해해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
