INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('debt', '빚', '[{"pos": "n.", "ko": "빚, 부채"}, {"pos": "n.", "ko": "신세, 은혜"}]'::jsonb, 'He worked hard to pay off his debt after college.', '그는 대학 졸업 후 빚을 갚기 위해 열심히 일했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decade', '10년', '[{"pos": "n.", "ko": "10년, 10년간"}]'::jsonb, 'A lot can change in a single decade.', '10년 만에도 많은 것이 변할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
