INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decline', '감소하다', '[{"pos": "v.", "ko": "수량이나 질이 줄어들다, 감소하다"}, {"pos": "v.", "ko": "(정중히) 거절하다"}, {"pos": "n.", "ko": "감소, 하락"}]'::jsonb, 'The population of the city continues to decline every year.', '그 도시의 인구는 해마다 계속 줄어들고 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decorate', '장식하다', '[{"pos": "v.", "ko": "장식하다, 꾸미다"}, {"pos": "v.", "ko": "훈장을 수여하다"}]'::jsonb, 'They decorated the classroom with balloons for the festival.', '그들은 축제를 위해 교실을 풍선으로 꾸몄다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('decrease', '감소하다', '[{"pos": "v.", "ko": "수나 양이 줄다, 감소하다"}, {"pos": "v.", "ko": "줄이다, 감소시키다"}, {"pos": "n.", "ko": "감소, 축소"}]'::jsonb, 'The company’s profits began to decrease after the new law was passed.', '새 법이 통과된 후 그 회사의 이익이 줄기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dedicate', '헌신하다', '[{"pos": "v.", "ko": "시간이나 노력을 바치다, 헌신하다"}, {"pos": "v.", "ko": "(건물·책 등을) 헌정하다"}]'::jsonb, 'She decided to dedicate her life to helping the poor.', '그녀는 가난한 사람들을 돕는 데 평생을 바치기로 결심했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
