INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('defect', '결함', '[{"pos": "n.", "ko": "결점, 결함, 흠"}]'::jsonb, 'The product was recalled due to a serious safety defect.', '그 제품은 심각한 안전 결함 때문에 리콜되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('defend', '방어하다', '[{"pos": "v.", "ko": "공격이나 위험으로부터 지키다, 방어하다"}, {"pos": "v.", "ko": "옹호하다, 변호하다"}]'::jsonb, 'The soldiers were trained to defend the country from any threat.', '군인들은 어떤 위협으로부터도 나라를 방어하도록 훈련받았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
