INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('delay', '연기하다', '[{"pos": "v.", "ko": "연기하다, 늦추다"}, {"pos": "n.", "ko": "지연, 연기"}]'::jsonb, 'The heavy rain may delay the start of the soccer match.', '폭우로 축구 경기가 시작이 연기될 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('delicate', '섬세한', '[{"pos": "a.", "ko": "섬세한, 정교한"}, {"pos": "a.", "ko": "연약한, 깨지기 쉬운"}, {"pos": "a.", "ko": "민감한, 다루기 어려운"}]'::jsonb, 'The artist used delicate brushstrokes to create a soft effect.', '그 화가는 부드러운 효과를 내기 위해 섬세한 붓질을 사용했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
