INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('departure', '출발', '[{"pos": "n.", "ko": "떠남, 출발"}]'::jsonb, 'Please arrive at the airport two hours before your departure.', '출발 두 시간 전에 공항에 도착해 주세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
