INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deposit', '보증금', '[{"pos": "n.", "ko": "보증금, 계약금"}, {"pos": "n.", "ko": "예금, 예치금"}, {"pos": "n.", "ko": "퇴적물, 침전물"}, {"pos": "v.", "ko": "예금하다, 입금하다"}, {"pos": "v.", "ko": "놓다, 두다"}, {"pos": "v.", "ko": "퇴적시키다, 침전시키다"}]'::jsonb, 'You must pay a deposit to reserve a hotel room.', '호텔 방을 예약하려면 보증금을 내야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('depression', '우울', '[{"pos": "n.", "ko": "우울, 우울증"}, {"pos": "n.", "ko": "불경기, 경기 침체"}]'::jsonb, 'Many people experience depression at some point in their lives.', '많은 사람들이 인생에서 한 번쯤은 우울을 겪는다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
