INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('describe', '묘사하다', '[{"pos": "v.", "ko": "묘사하다, 설명하다"}, {"pos": "v.", "ko": "특징을 말하다"}]'::jsonb, 'Please describe the main character in your own words.', '주인공을 네 말로 묘사해 보아라.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('desert', '사막', '[{"pos": "n.", "ko": "모래와 바위로 이루어진 사막"}, {"pos": "v.", "ko": "사람이나 장소를 버리다"}, {"pos": "v.", "ko": "의무나 책임을 저버리다"}]'::jsonb, 'The camel can survive for weeks without water in the desert.', '낙타는 사막에서 몇 주 동안 물 없이도 살 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('deserve', '받을 자격이 있다', '[{"pos": "v.", "ko": "받을 자격이 있다"}, {"pos": "v.", "ko": "~할 만하다"}]'::jsonb, 'You deserve to be praised for your hard work and dedication.', '너는 노력과 헌신으로 칭찬받을 자격이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('despair', '절망', '[{"pos": "n.", "ko": "절망, 좌절"}, {"pos": "v.", "ko": "절망하다, 희망을 잃다"}]'::jsonb, 'She fell into despair after hearing the disappointing news.', '실망스러운 소식을 듣고 그녀는 절망에 빠졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
