INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('destination', '목적지', '[{"pos": "n.", "ko": "목적지, 행선지"}]'::jsonb, 'The train will arrive at its final destination in two hours.', '기차는 두 시간 후에 최종 목적지에 도착할 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
