INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('dietary', '식이의', '[{"pos": "a.", "ko": "식이의, 음식과 관련된"}, {"pos": "a.", "ko": "식단의"}]'::jsonb, 'She follows strict dietary guidelines to maintain her health.', '그녀는 건강을 위해 엄격한 식이 지침을 따른다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
