INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('diminish', '감소하다', '[{"pos": "v.", "ko": "감소하다, 줄다"}, {"pos": "v.", "ko": "줄이다, 축소하다"}]'::jsonb, 'The pain will gradually diminish as your injury heals.', '부상이 회복되면서 통증이 점차 감소할 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('diplomat', '외교관', '[{"pos": "n.", "ko": "외교관"}]'::jsonb, 'The diplomat attended the international conference to represent his country.', '그 외교관은 자국을 대표해 국제 회의에 참석했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('direct', '직접의', '[{"pos": "a.", "ko": "직접의, 직접적인"}, {"pos": "a.", "ko": "직행의, 직통의"}, {"pos": "v.", "ko": "(주의, 노력 등을) 돌리다, 향하게 하다"}, {"pos": "v.", "ko": "지도하다, 감독하다"}, {"pos": "v.", "ko": "길을 안내하다"}, {"pos": "v.", "ko": "명령하다, 지시하다"}]'::jsonb, 'There is a direct flight from Seoul to Paris every day.', '서울에서 파리로 가는 직항편이 매일 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
