INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emergency', '비상 상황', '[{"pos": "n.", "ko": "비상 상황, 긴급 사태"}, {"pos": "n.", "ko": "위급함"}]'::jsonb, 'In case of an emergency, follow the instructions given by the staff.', '비상 상황에는 직원의 안내에 따라야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emission', '배출', '[{"pos": "n.", "ko": "배출, 방출 (가스, 빛 등)"}, {"pos": "n.", "ko": "배출물, 방출된 것"}]'::jsonb, 'Car emission standards have become stricter to protect the environment.', '환경 보호를 위해 자동차 배출 기준이 더 엄격해졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emotion', '감정', '[{"pos": "n.", "ko": "감정, 정서"}]'::jsonb, 'He tried to hide his emotion during the farewell ceremony.', '그는 이별식에서 자신의 감정을 숨기려 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empathy', '공감', '[{"pos": "n.", "ko": "공감, 감정 이입"}]'::jsonb, 'Empathy helps people build strong and supportive relationships.', '공감은 사람들이 돈독하고 서로 돕는 관계를 만드는 데 도움이 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('emphasize', '강조하다', '[{"pos": "v.", "ko": "강조하다, 두드러지게 하다"}, {"pos": "v.", "ko": "중요하게 여기다"}, {"pos": "v.", "ko": "강하게 발음하다"}]'::jsonb, 'The coach emphasized the need for teamwork before the game started.', '감독은 경기가 시작되기 전에 팀워크의 필요성을 강조했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('employ', '고용하다', '[{"pos": "v.", "ko": "고용하다, 일자리를 주다"}, {"pos": "v.", "ko": "(방법·기술 등을) 사용하다"}, {"pos": "v.", "ko": "시간을 쓰다"}]'::jsonb, 'The company decided to employ more workers for the new project.', '그 회사는 새 프로젝트를 위해 더 많은 직원을 고용하기로 결정했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('empower', '권한을 주다', '[{"pos": "v.", "ko": "권한을 주다, 힘을 실어주다"}, {"pos": "v.", "ko": "자율성을 높이다"}, {"pos": "v.", "ko": "허락하다, 허가하다"}]'::jsonb, 'The program aims to empower students to make their own decisions.', '그 프로그램은 학생들에게 스스로 결정할 수 있는 권한을 주는 것을 목표로 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('enable', '가능하게 하다', '[{"pos": "v.", "ko": "가능하게 하다, 할 수 있게 해 주다"}, {"pos": "v.", "ko": "허용하다, 허락하다"}]'::jsonb, 'This new technology will enable doctors to treat patients more effectively.', '이 새로운 기술은 의사들이 환자를 더 효과적으로 치료할 수 있게 해 줄 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('encounter', '직면하다', '[{"pos": "v.", "ko": "(문제 등에) 직면하다, 맞닥뜨리다"}, {"pos": "v.", "ko": "우연히 만나다"}, {"pos": "n.", "ko": "(예상 밖의) 만남, 조우"}]'::jsonb, 'You may encounter many difficulties when starting a new business.', '새로운 사업을 시작할 때 많은 어려움에 직면할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('encourage', '격려하다', '[{"pos": "v.", "ko": "용기를 북돋우다, 격려하다"}, {"pos": "v.", "ko": "장려하다, 촉진하다"}, {"pos": "v.", "ko": "응원하다"}]'::jsonb, 'Parents should encourage their children to try new activities.', '부모는 자녀가 새로운 활동에 도전하도록 격려해야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('end up -ing', '결국 ~하다', '[{"pos": "phr.", "ko": "결국 ~하게 되다"}, {"pos": "phr.", "ko": "~하는 것으로 끝나다"}]'::jsonb, 'He studied hard but ended up failing the test.', '그는 열심히 공부했지만 결국 시험에 떨어졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('endangered', '멸종 위기의', '[{"pos": "a.", "ko": "멸종 위기에 처한"}, {"pos": "a.", "ko": "위험에 놓인"}]'::jsonb, 'Many endangered animals need our help to survive in the wild.', '많은 멸종 위기 동물들이 야생에서 살아남기 위해 우리의 도움이 필요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
