INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('essential', '필수적인', '[{"pos": "a.", "ko": "꼭 필요한, 필수적인"}, {"pos": "a.", "ko": "본질적인, 근본적인"}]'::jsonb, 'Water is essential for all living things to survive on Earth.', '물은 모든 생명체가 지구에서 살아가는 데 꼭 필요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
