INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ethnic', '민족의', '[{"pos": "a.", "ko": "민족의, 인종의"}, {"pos": "a.", "ko": "민족 특유의"}]'::jsonb, 'The city is known for its diverse ethnic communities.', '그 도시는 다양한 민족 공동체로 유명하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
