INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('exceed', '넘다', '[{"pos": "v.", "ko": "넘다, 초과하다"}, {"pos": "v.", "ko": "(한도를) 넘어서다"}]'::jsonb, 'Do not exceed the recommended dosage of this medicine.', '이 약의 권장 복용량을 넘지 마세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
