INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('excess', '초과', '[{"pos": "n.", "ko": "초과, 과잉"}, {"pos": "n.", "ko": "지나침, 과도함"}, {"pos": "a.", "ko": "초과의, 여분의"}]'::jsonb, 'Eating in excess can lead to health problems over time.', '음식을 지나치게 먹으면 시간이 지나 건강에 문제가 생길 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
