INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('humid', '습한', '[{"pos": "a.", "ko": "습한, 습기가 많은"}]'::jsonb, 'It was so humid that everyone felt uncomfortable during the afternoon.', '오후 내내 너무 습해서 모두가 불편함을 느꼈다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
