INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illegal', '불법의', '[{"pos": "a.", "ko": "불법의, 법에 어긋나는"}]'::jsonb, 'It is illegal to drive without a valid license in most countries.', '대부분의 나라에서 유효한 면허 없이 운전하는 것은 불법이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
