INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('illustrate', '설명하다', '[{"pos": "v.", "ko": "설명하다, 예시를 들다"}, {"pos": "v.", "ko": "삽화를 넣다"}]'::jsonb, 'The teacher used a diagram to illustrate how the water cycle works.', '선생님은 물의 순환 과정을 설명하기 위해 도표를 사용했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('imaginative', '상상력이 풍부한', '[{"pos": "a.", "ko": "상상력이 풍부한"}, {"pos": "a.", "ko": "창의적인"}, {"pos": "a.", "ko": "독창적인"}]'::jsonb, 'The teacher praised her for her imaginative solution to the problem.', '선생님은 그녀의 상상력이 풍부한 문제 해결법을 칭찬했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('imitate', '모방하다', '[{"pos": "v.", "ko": "모방하다"}, {"pos": "v.", "ko": "흉내내다"}, {"pos": "v.", "ko": "따라하다"}]'::jsonb, 'Children often imitate the behavior of adults around them.', '아이들은 주변 어른들의 행동을 자주 모방한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('immediate', '즉각적인', '[{"pos": "a.", "ko": "즉각적인"}, {"pos": "a.", "ko": "당면한"}, {"pos": "a.", "ko": "가까운"}]'::jsonb, 'The patient required immediate medical attention after the accident.', '그 환자는 사고 후 즉각적인 치료가 필요했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('immigration', '이민', '[{"pos": "n.", "ko": "이민"}, {"pos": "n.", "ko": "이주"}]'::jsonb, 'The government is discussing new policies to manage immigration.', '정부는 이민을 관리하기 위한 새로운 정책을 논의하고 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('immune', '면역이 있는', '[{"pos": "a.", "ko": "면역이 있는"}, {"pos": "a.", "ko": "면제된"}]'::jsonb, 'After recovering from the disease, he became immune to it.', '그는 병을 앓고 나서 그 질병에 면역이 생겼다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
