INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('impatient', '참을성 없는', '[{"pos": "a.", "ko": "참을성 없는"}, {"pos": "a.", "ko": "조급한"}]'::jsonb, 'He grew impatient while waiting for the results to be announced.', '그는 결과 발표를 기다리며 참을성 없게 되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('implement', '도구', '[{"pos": "n.", "ko": "도구, 연장"}, {"pos": "v.", "ko": "실행하다, 이행하다"}]'::jsonb, 'The farmer used a new implement to make his work easier.', '그 농부는 일을 더 쉽게 하려고 새 도구를 사용했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('imply', '내포하다', '[{"pos": "v.", "ko": "내포하다, 함축하다"}, {"pos": "v.", "ko": "암시하다, 넌지시 비추다"}]'::jsonb, 'His silence seemed to imply that he disagreed with the plan.', '그의 침묵은 그가 그 계획에 동의하지 않음을 내포하는 듯했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('impressive', '인상적인', '[{"pos": "a.", "ko": "인상적인, 감명을 주는"}]'::jsonb, 'The students gave an impressive performance at the festival.', '학생들은 축제에서 인상적인 공연을 선보였다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
