INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('improve', '향상시키다', '[{"pos": "v.", "ko": "향상시키다, 개선하다"}]'::jsonb, 'Regular exercise can improve your physical and mental health.', '규칙적인 운동은 신체와 정신 건강을 향상시킬 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('impulse', '충동', '[{"pos": "n.", "ko": "충동, 자극"}, {"pos": "n.", "ko": "추진력"}]'::jsonb, 'On an impulse, she bought a ticket to the concert.', '그녀는 충동적으로 콘서트 티켓을 샀다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
