INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('incentive', '장려책', '[{"pos": "n.", "ko": "장려책, 유인"}, {"pos": "n.", "ko": "보상, 동기"}]'::jsonb, 'The company offered an incentive to employees who met their sales goals.', '회사는 판매 목표를 달성한 직원들에게 장려책을 제공했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('incline', '기울다', '[{"pos": "v.", "ko": "기울다, 기울이다"}, {"pos": "v.", "ko": "~할 마음이 내키게 하다"}, {"pos": "v.", "ko": "(생각·감정이) 쏠리다"}]'::jsonb, 'The road begins to incline as you approach the mountain.', '산에 가까워질수록 도로가 기울기 시작한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
