INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('independence', '독립', '[{"pos": "n.", "ko": "독립"}, {"pos": "n.", "ko": "자립"}]'::jsonb, 'The country celebrates its independence every year with a big festival.', '그 나라는 매년 큰 축제로 독립을 기념한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
