INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('inhabit', '살다', '[{"pos": "v.", "ko": "살다"}, {"pos": "v.", "ko": "거주하다"}, {"pos": "v.", "ko": "서식하다"}]'::jsonb, 'Many rare animals inhabit this forest.', '이 숲에는 많은 희귀 동물들이 산다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
