INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('innate', '선천적인', '[{"pos": "a.", "ko": "선천적인, 타고난"}]'::jsonb, 'Some people have an innate talent for music from a young age.', '어떤 사람들은 어릴 때부터 선천적으로 음악에 재능이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
