INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('ironically', '아이러니하게', '[{"pos": "ad.", "ko": "아이러니하게도, 반어적으로"}, {"pos": "ad.", "ko": "뜻밖에도"}]'::jsonb, 'Ironically, the fire station caught fire during the safety drill.', '아이러니하게도, 소방서가 안전 훈련 중에 불이 났다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
