INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('isolate', '고립시키다', '[{"pos": "v.", "ko": "고립시키다, 격리하다"}, {"pos": "v.", "ko": "분리하다, 떼어놓다"}]'::jsonb, 'Doctors had to isolate the patient to prevent the disease from spreading.', '의사들은 질병 확산을 막기 위해 환자를 고립시켜야 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('issue', '문제', '[{"pos": "n.", "ko": "문제, 논쟁점"}, {"pos": "n.", "ko": "발행물, 출판물"}, {"pos": "v.", "ko": "발표하다, 공표하다"}, {"pos": "v.", "ko": "발행하다, 내주다"}]'::jsonb, 'Environmental pollution has become a serious issue in many cities.', '환경 오염은 많은 도시에서 심각한 문제가 되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
