INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('judgment', '판단', '[{"pos": "n.", "ko": "판단, 판단력"}, {"pos": "n.", "ko": "판정, 결정"}, {"pos": "n.", "ko": "판결, 재판 결과"}]'::jsonb, 'Good judgment is important when making difficult choices in life.', '인생에서 어려운 선택을 할 때는 올바른 판단이 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
