INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('keep A from -ing', '~하지 못하게 하다', '[{"pos": "phr.", "ko": "A가 ~하지 못하게 하다"}]'::jsonb, 'Strict rules keep students from using their phones during class.', '엄격한 규칙이 학생들이 수업 중에 휴대폰을 사용하지 못하게 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
