INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('knowledge', '지식', '[{"pos": "n.", "ko": "지식, 학식"}, {"pos": "n.", "ko": "알고 있음, 인식"}]'::jsonb, 'Knowledge gained from books can help you solve real-life problems.', '책에서 얻은 지식은 실제 문제를 푸는 데 도움이 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
