INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('mislead', '오도하다', '[{"pos": "v.", "ko": "잘못 이끌다, 오도하다"}, {"pos": "v.", "ko": "속이다, 오해하게 하다"}]'::jsonb, 'The advertisement was designed to mislead customers about the product''s quality.', '그 광고는 제품의 품질에 대해 소비자를 오도하도록 만들어졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('mixture', '혼합물', '[{"pos": "n.", "ko": "혼합물, 섞인 것"}, {"pos": "n.", "ko": "혼합, 섞기"}]'::jsonb, 'The cake batter is a mixture of flour, eggs, and sugar.', '케이크 반죽은 밀가루, 달걀, 설탕이 섞인 혼합물이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('mobile', '이동이 쉬운', '[{"pos": "a.", "ko": "이동이 쉬운, 움직일 수 있는"}, {"pos": "n.", "ko": "모빌(장식용 매달린 조각), 휴대전화"}]'::jsonb, 'The mobile library visits small towns every week to lend books.', '이동 도서관은 매주 작은 마을을 방문해 책을 빌려준다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('modern', '현대의', '[{"pos": "a.", "ko": "현대의, 근대의"}, {"pos": "a.", "ko": "현대적인, 최신의"}]'::jsonb, 'Modern technology has changed the way people communicate.', '현대 기술은 사람들이 소통하는 방식을 바꿔 놓았다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('modify', '변경하다', '[{"pos": "v.", "ko": "변경하다, 수정하다"}, {"pos": "v.", "ko": "수식하다"}]'::jsonb, 'You can modify the schedule if you need more time.', '더 시간이 필요하면 일정을 변경할 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('molecule', '분자', '[{"pos": "n.", "ko": "분자"}]'::jsonb, 'A water molecule is made up of two hydrogen atoms and one oxygen atom.', '물 분자는 수소 원자 두 개와 산소 원자 한 개로 이루어져 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('moment', '순간', '[{"pos": "n.", "ko": "순간, 아주 짧은 시간"}, {"pos": "n.", "ko": "특정한 때, 시기"}]'::jsonb, 'She hesitated for a moment before answering the question.', '그녀는 질문에 답하기 전에 잠시 망설였다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('moral', '도덕적인', '[{"pos": "a.", "ko": "도덕적인, 옳고 그름에 관한"}, {"pos": "n.", "ko": "교훈, 도덕적 의미"}]'::jsonb, 'She always tries to make moral decisions in difficult situations.', '그녀는 어려운 상황에서도 항상 도덕적인 결정을 내리려고 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('morale', '사기', '[{"pos": "n.", "ko": "의욕, 사기"}, {"pos": "n.", "ko": "집단의 정신 상태"}]'::jsonb, 'The team''s morale improved after their recent victory.', '최근 승리로 팀의 사기가 높아졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('mortal', '죽을 운명의', '[{"pos": "a.", "ko": "언젠가는 죽는, 죽을 운명의"}, {"pos": "a.", "ko": "치명적인"}, {"pos": "n.", "ko": "인간"}]'::jsonb, 'All humans are mortal and must face death someday.', '모든 인간은 죽을 운명이며 언젠가는 죽음을 맞이한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('motion', '움직임', '[{"pos": "n.", "ko": "움직임, 동작"}, {"pos": "v.", "ko": "몸짓으로 신호하다"}]'::jsonb, 'The sudden motion of the train startled the passengers.', '기차의 갑작스러운 움직임에 승객들이 놀랐다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('motivate', '동기를 주다', '[{"pos": "v.", "ko": "동기를 부여하다"}, {"pos": "v.", "ko": "자극하여 행동하게 하다"}]'::jsonb, 'Teachers should motivate students to reach their full potential.', '교사는 학생들이 잠재력을 발휘하도록 동기를 주어야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
