INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('muscle', '근육', '[{"pos": "n.", "ko": "근육"}, {"pos": "n.", "ko": "근력, 힘"}]'::jsonb, 'Regular exercise helps you build muscle and stay healthy.', '규칙적인 운동은 근육을 키우고 건강을 유지하는 데 도움이 된다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
