INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('obscure', '모호한', '[{"pos": "a.", "ko": "이해하기 어려운, 모호한"}, {"pos": "a.", "ko": "잘 알려지지 않은, 무명의"}, {"pos": "v.", "ko": "가리다, 흐리게 하다"}]'::jsonb, 'The meaning of the poem remains obscure even after several readings.', '그 시의 의미는 여러 번 읽어도 여전히 모호하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
