INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('observe', '관찰하다', '[{"pos": "v.", "ko": "관찰하다, 주시하다"}, {"pos": "v.", "ko": "지키다, 준수하다"}, {"pos": "v.", "ko": "알아차리다, 인지하다"}, {"pos": "v.", "ko": "(의견을) 말하다, 진술하다"}]'::jsonb, 'Scientists observe the changes in temperature during the experiment.', '과학자들은 실험 중 온도의 변화를 관찰한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
