INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('occupation', '직업', '[{"pos": "n.", "ko": "직업, 일"}, {"pos": "n.", "ko": "점령, 점유"}, {"pos": "n.", "ko": "여가 활동"}]'::jsonb, 'She chose teaching as her main occupation after graduating from university.', '그녀는 대학을 졸업한 후 교직을 자신의 주요 직업으로 선택했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
