INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('opinion', '의견', '[{"pos": "n.", "ko": "의견, 생각, 견해"}]'::jsonb, 'In my opinion, reading books is the best way to learn new things.', '내 생각에는 책을 읽는 것이 새로운 것을 배우는 가장 좋은 방법이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
