INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reflect', '반사하다', '[{"pos": "v.", "ko": "반사하다, 비추다"}, {"pos": "v.", "ko": "반영하다, 나타내다"}, {"pos": "v.", "ko": "숙고하다, 깊이 생각하다"}]'::jsonb, 'The surface of the lake reflected the mountains and the sky.', '호수 표면에 산과 하늘이 비쳤다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reform', '개혁하다', '[{"pos": "v.", "ko": "개혁하다, 개선하다"}, {"pos": "n.", "ko": "개혁, 개선"}, {"pos": "v.", "ko": "개선되다, 바로잡히다"}]'::jsonb, 'The government plans to reform the education system next year.', '정부는 내년에 교육 제도를 개혁할 계획이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
