INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('reliable', '믿을 만한', '[{"pos": "a.", "ko": "믿을 만한, 신뢰할 수 있는"}]'::jsonb, 'He is a reliable friend who always keeps his promises.', '그는 항상 약속을 지키는 믿을 만한 친구다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
