INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('research', '연구', '[{"pos": "n.", "ko": "연구, 조사"}, {"pos": "v.", "ko": "연구하다, 조사하다"}]'::jsonb, 'He spent several years conducting research on climate change.', '그는 기후 변화에 관한 연구를 몇 년간 진행했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
