INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('resistant', '내성이 있는', '[{"pos": "a.", "ko": "내성이 있는, 잘 견디는"}, {"pos": "a.", "ko": "저항하는, 반대하는"}]'::jsonb, 'Some bacteria are resistant to certain types of antibiotics.', '일부 박테리아는 특정 항생제에 내성이 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
