INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strain', '긴장', '[{"pos": "n.", "ko": "긴장, 피로"}, {"pos": "n.", "ko": "부담, 중압"}, {"pos": "v.", "ko": "애쓰다, 노력하다"}, {"pos": "v.", "ko": "(근육 등을) 혹사시키다"}]'::jsonb, 'Preparing for the exam put a lot of strain on the students.', '시험 준비로 학생들은 큰 긴장을 겪었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
