INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('straw', '빨대', '[{"pos": "n.", "ko": "빨대"}, {"pos": "n.", "ko": "짚, 건초"}, {"pos": "n.", "ko": "사소한 것"}]'::jsonb, 'She drank her juice through a yellow plastic straw.', '그녀는 노란색 플라스틱 빨대로 주스를 마셨다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strengthen', '강화하다', '[{"pos": "v.", "ko": "강화하다, 더 튼튼하게 하다"}, {"pos": "v.", "ko": "강해지다, 힘을 얻다"}]'::jsonb, 'Regular exercise can strengthen your muscles and improve your health.', '규칙적인 운동은 근육을 강화하고 건강을 증진시킨다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stress', '스트레스', '[{"pos": "n.", "ko": "긴장, 스트레스"}, {"pos": "n.", "ko": "압박, 중점"}, {"pos": "v.", "ko": "강조하다, 중점을 두다"}]'::jsonb, 'Too much stress can affect your ability to concentrate in class.', '지나친 스트레스는 수업에서 집중력을 떨어뜨릴 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stretch', '뻗다', '[{"pos": "v.", "ko": "쭉 뻗다, 늘이다"}, {"pos": "n.", "ko": "뻗기, 신장"}, {"pos": "v.", "ko": "(시간·범위 등을) 연장하다"}]'::jsonb, 'He stood up and stretched his arms after sitting for a long time.', '오랫동안 앉아 있던 그는 일어나서 팔을 쭉 뻗었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('strict', '엄격한', '[{"pos": "a.", "ko": "엄격한, 엄한"}, {"pos": "a.", "ko": "정확한, 엄밀한"}]'::jsonb, 'Our teacher is very strict about homework deadlines.', '우리 선생님은 숙제 제출 기한에 매우 엄격하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('stroke', '뇌졸중', '[{"pos": "n.", "ko": "뇌졸중"}, {"pos": "n.", "ko": "타격, 한 번 치기"}, {"pos": "n.", "ko": "쓰다듬기, 어루만지기"}]'::jsonb, 'Quick medical attention is crucial when someone has a stroke.', '누군가 뇌졸중이 오면 신속한 치료가 매우 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('struggle', '고군분투하다', '[{"pos": "v.", "ko": "고군분투하다, 힘겹게 싸우다"}, {"pos": "n.", "ko": "분투, 노력"}]'::jsonb, 'She had to struggle to balance her studies and part-time job.', '그녀는 학업과 아르바이트를 병행하려고 고군분투했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('subject', '주제', '[{"pos": "n.", "ko": "주제, 화제"}, {"pos": "n.", "ko": "과목, 학과"}, {"pos": "n.", "ko": "피실험자, 대상"}, {"pos": "a.", "ko": "영향받기 쉬운, 지배를 받는"}, {"pos": "v.", "ko": "지배하다, 복종시키다"}]'::jsonb, 'The main subject of the discussion was how to improve student safety.', '토론의 주요 주제는 학생 안전을 어떻게 높일지였다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('subjective', '주관적인', '[{"pos": "a.", "ko": "주관적인, 개인적인"}]'::jsonb, 'Your opinion about the movie is subjective and may differ from others.', '그 영화에 대한 너의 평가는 주관적이어서 다른 사람들과 다를 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('submit', '제출하다', '[{"pos": "v.", "ko": "제출하다"}, {"pos": "v.", "ko": "복종하다, 굴복하다"}]'::jsonb, 'Please submit your application form before the end of this week.', '이번 주가 끝나기 전에 신청서를 제출하세요.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('substance', '물질', '[{"pos": "n.", "ko": "물질, 재료"}, {"pos": "n.", "ko": "본질, 핵심"}, {"pos": "n.", "ko": "요지, 중요한 부분"}]'::jsonb, 'Water is a common substance that is essential for all living things.', '물은 모든 생명체에 꼭 필요한 흔한 물질이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('substitute', '대체하다', '[{"pos": "v.", "ko": "대체하다, 대신 쓰다"}, {"pos": "n.", "ko": "대용품, 대리인"}]'::jsonb, 'You can substitute honey for sugar in this recipe to make it healthier.', '이 조리법에서 설탕 대신 꿀을 사용하면 더 건강하게 만들 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('success', '성공', '[{"pos": "n.", "ko": "성공, 성취"}, {"pos": "n.", "ko": "출세"}]'::jsonb, 'Her success as a writer inspired many young people to follow their dreams.', '그녀의 작가로서의 성공은 많은 젊은이들에게 꿈을 따르도록 영감을 주었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('successful', '성공적인', '[{"pos": "a.", "ko": "성공적인, 성과 있는"}, {"pos": "a.", "ko": "출세한"}]'::jsonb, 'The project was successful thanks to the team''s hard work and cooperation.', '팀의 노력과 협력 덕분에 그 프로젝트는 성공적이었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('successive', '연속적인', '[{"pos": "a.", "ko": "연속적인, 계속되는"}]'::jsonb, 'He won three successive championships in his sporting career.', '그는 운동 선수 생활 동안 세 번 연속으로 우승했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sudden', '갑작스러운', '[{"pos": "a.", "ko": "갑작스러운, 예기치 않은"}]'::jsonb, 'There was a sudden change in the weather during our picnic.', '소풍 중에 날씨가 갑자기 변했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sue', '고소하다', '[{"pos": "v.", "ko": "고소하다, 소송을 제기하다"}]'::jsonb, 'The customer decided to sue the company for selling defective products.', '고객은 결함 있는 제품을 판매한 회사에 대해 고소하기로 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suffer from', '~로 고통받다', '[{"pos": "phr.", "ko": "~로 고통받다, ~을 앓다"}]'::jsonb, 'She began to suffer from severe headaches after the accident.', '그녀는 사고 이후 심한 두통에 시달리기 시작했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sufficient', '충분한', '[{"pos": "a.", "ko": "충분한, 만족할 만한"}]'::jsonb, 'There was sufficient evidence to support the scientist''s theory.', '그 과학자의 이론을 뒷받침할 충분한 증거가 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suit', '적합하다', '[{"pos": "v.", "ko": "적합하다, 알맞다"}, {"pos": "v.", "ko": "어울리다, 잘 맞다"}, {"pos": "n.", "ko": "정장, 한 벌의 옷"}, {"pos": "n.", "ko": "소송"}]'::jsonb, 'This job would suit someone who enjoys working with people.', '이 일은 사람들과 일하는 것을 좋아하는 사람에게 적합하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suitable', '적합한', '[{"pos": "a.", "ko": "적합한, 알맞은"}, {"pos": "a.", "ko": "적절한"}]'::jsonb, 'These shoes are suitable for hiking in the mountains.', '이 신발은 산에서 등산하기에 적합하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('superior', '우수한', '[{"pos": "a.", "ko": "우수한, 더 나은"}, {"pos": "a.", "ko": "상위의, 상급의"}, {"pos": "n.", "ko": "상사, 상급자"}]'::jsonb, 'This model is superior to the previous one in both speed and design.', '이 모델은 속도와 디자인 면에서 이전 것보다 우수하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
