INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('supplement', '보충물', '[{"pos": "n.", "ko": "보충물, 추가물"}, {"pos": "v.", "ko": "보충하다, 추가하다"}]'::jsonb, 'Many people take a vitamin supplement to improve their health.', '많은 사람들이 건강을 위해 비타민 보충제를 먹는다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('supply', '공급', '[{"pos": "n.", "ko": "공급, 제공"}, {"pos": "n.", "ko": "비축품, 보급품"}, {"pos": "v.", "ko": "공급하다, 제공하다"}]'::jsonb, 'There was a limited supply of water during the drought.', '가뭄 때는 물 공급이 제한적이었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('support', '지지하다', '[{"pos": "v.", "ko": "지지하다, 옹호하다"}, {"pos": "v.", "ko": "부양하다, 경제적으로 돕다"}, {"pos": "n.", "ko": "지지, 지원"}]'::jsonb, 'Many students support the new school policy for longer breaks.', '많은 학생들이 쉬는 시간을 늘리는 새로운 학교 정책을 지지한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suppose', '추정하다', '[{"pos": "v.", "ko": "추정하다, 생각하다"}, {"pos": "v.", "ko": "가정하다, 상상하다"}]'::jsonb, 'I suppose the meeting will end before six o''clock today.', '나는 오늘 회의가 여섯 시 전에 끝날 거라고 생각한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('surface', '표면', '[{"pos": "n.", "ko": "표면, 외부"}, {"pos": "v.", "ko": "(수면이나 땅 위로) 나타나다, 드러나다"}]'::jsonb, 'The surface of the desk was covered with books and papers.', '책상 표면이 책과 종이로 가득 덮여 있었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('surgery', '수술', '[{"pos": "n.", "ko": "수술"}, {"pos": "n.", "ko": "외과학"}]'::jsonb, 'The patient recovered quickly after heart surgery.', '환자는 심장 수술 후 빠르게 회복했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('survive', '살아남다', '[{"pos": "v.", "ko": "살아남다, 생존하다"}, {"pos": "v.", "ko": "견디다, 극복하다"}, {"pos": "v.", "ko": "~보다 오래 살다"}]'::jsonb, 'Only a few animals survived the harsh winter in the mountains.', '산에서 혹독한 겨울을 살아남은 동물은 몇 마리뿐이었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('suspect', '의심하다', '[{"pos": "v.", "ko": "의심하다, 혐의를 두다"}, {"pos": "v.", "ko": "~라고 생각하다"}, {"pos": "n.", "ko": "용의자, 수상한 사람"}]'::jsonb, 'The police suspect that the fire was started on purpose.', '경찰은 그 화재가 고의로 일어났다고 의심한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sustainable', '지속 가능한', '[{"pos": "a.", "ko": "지속 가능한, 유지할 수 있는"}]'::jsonb, 'We need to find sustainable ways to produce energy for the future.', '우리는 미래를 위해 지속 가능한 에너지 생산 방법을 찾아야 한다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('sweep', '쓸다', '[{"pos": "v.", "ko": "쓸다, 청소하다"}, {"pos": "v.", "ko": "휩쓸다, 급속히 퍼지다"}]'::jsonb, 'He used a broom to sweep the floor every morning.', '그는 매일 아침 빗자루로 바닥을 쓸었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('symptom', '증상', '[{"pos": "n.", "ko": "증상, 징후"}, {"pos": "n.", "ko": "조짐, 신호"}]'::jsonb, 'A cough can be a symptom of a cold or flu.', '기침은 감기나 독감의 증상일 수 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
