INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('target', '목표', '[{"pos": "n.", "ko": "목표, 표적"}, {"pos": "n.", "ko": "대상, 목표물"}, {"pos": "v.", "ko": "목표로 삼다, 겨냥하다"}]'::jsonb, 'The company set a high sales target for this year.', '회사는 올해 높은 판매 목표를 세웠다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temperate', '온화한', '[{"pos": "a.", "ko": "온화한, 따뜻한"}, {"pos": "a.", "ko": "절제하는, 지나치지 않는"}, {"pos": "a.", "ko": "온건한, 극단적이지 않은"}]'::jsonb, 'The temperate climate of the region makes it ideal for growing grapes.', '그 지역의 온화한 기후는 포도를 재배하기에 이상적이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('temperature', '온도', '[{"pos": "n.", "ko": "온도, 기온"}, {"pos": "n.", "ko": "체온"}]'::jsonb, 'The temperature dropped quickly after the sun set behind the mountains.', '해가 산 뒤로 지자 온도가 급격히 떨어졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
