INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('theme', '주제', '[{"pos": "n.", "ko": "주제, 테마"}]'::jsonb, 'The main theme of the novel is overcoming adversity.', '그 소설의 주요 주제는 역경 극복이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
