INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('visual', '시각의', '[{"pos": "a.", "ko": "시각의, 눈으로 보는"}, {"pos": "a.", "ko": "시각적 효과의, 그림의"}]'::jsonb, 'The teacher used visual aids to explain the lesson.', '선생님은 수업 설명을 위해 시각 자료를 사용했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('vital', '매우 중요한', '[{"pos": "a.", "ko": "매우 중요한, 필수적인"}, {"pos": "a.", "ko": "생명 유지에 필요한"}, {"pos": "a.", "ko": "활기찬, 생기가 넘치는"}]'::jsonb, 'Water is vital for the survival of all living things.', '물은 모든 생명체의 생존에 매우 중요하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('vogue', '유행', '[{"pos": "n.", "ko": "유행, 인기"}, {"pos": "n.", "ko": "(일시적인) 대유행"}]'::jsonb, 'Short skirts are back in vogue this season.', '이번 시즌에는 짧은 치마가 다시 유행하고 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('volcanic', '화산의', '[{"pos": "a.", "ko": "화산의, 화산과 관련된"}, {"pos": "a.", "ko": "화산이 분출하는"}]'::jsonb, 'The island was formed by volcanic activity thousands of years ago.', '그 섬은 수천 년 전 화산 활동으로 형성되었다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('voluntary', '자발적인', '[{"pos": "a.", "ko": "자발적인, 자진해서 하는"}, {"pos": "a.", "ko": "자원봉사의, 무보수의"}]'::jsonb, 'Participation in the program is completely voluntary.', '이 프로그램 참여는 전적으로 자발적이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('waist', '허리', '[{"pos": "n.", "ko": "허리"}]'::jsonb, 'She tied a belt around her waist to fit her dress better.', '그녀는 드레스가 더 잘 맞도록 허리에 벨트를 맸다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
