INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('waste', '낭비하다', '[{"pos": "v.", "ko": "낭비하다"}, {"pos": "n.", "ko": "낭비"}, {"pos": "n.", "ko": "쓰레기"}]'::jsonb, 'You shouldn''t waste water by leaving the tap running.', '수돗물을 틀어 놓은 채로 두면 물을 낭비하는 것이다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('wasteful', '낭비하는', '[{"pos": "a.", "ko": "낭비하는"}, {"pos": "a.", "ko": "비효율적인"}]'::jsonb, 'Buying more food than you need is wasteful and expensive.', '필요 이상으로 음식을 사는 것은 낭비이고 비용도 많이 든다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
