INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('weed', '잡초', '[{"pos": "n.", "ko": "잡초"}, {"pos": "v.", "ko": "잡초를 뽑다, 제거하다"}]'::jsonb, 'The garden was full of weeds after the long rainy season.', '오랜 장마가 끝난 뒤 정원에는 잡초가 가득했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('welfare', '복지', '[{"pos": "n.", "ko": "복지, 사회복지"}, {"pos": "n.", "ko": "행복, 안녕"}]'::jsonb, 'The government increased its budget to improve public welfare.', '정부는 국민 복지 향상을 위해 예산을 늘렸다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('widespread', '널리 퍼진', '[{"pos": "a.", "ko": "널리 퍼진, 광범위한"}]'::jsonb, 'There is widespread concern about climate change around the world.', '전 세계적으로 기후 변화에 대한 우려가 널리 퍼져 있다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('wield', '휘두르다', '[{"pos": "v.", "ko": "(무기·도구 등을) 휘두르다, 사용하다"}, {"pos": "v.", "ko": "(권력 등을) 행사하다"}]'::jsonb, 'The knight could skillfully wield his sword in battle.', '그 기사(기사)는 전투에서 능숙하게 검을 휘둘렀다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('wire', '철사', '[{"pos": "n.", "ko": "철사, 전선"}, {"pos": "v.", "ko": "전선을 연결하다"}]'::jsonb, 'The fence was made of strong wire to keep animals out.', '그 울타리는 동물들이 들어오지 못하게 튼튼한 철사로 만들어졌다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('withdraw', '인출하다', '[{"pos": "v.", "ko": "(예금 등을) 인출하다"}, {"pos": "v.", "ko": "철수하다, 물러나다"}, {"pos": "v.", "ko": "(약속·지원 등을) 철회하다"}, {"pos": "v.", "ko": "(조직·학교 등을) 그만두다"}]'::jsonb, 'She had to withdraw some money from her bank account to pay the bills.', '그녀는 청구서를 내기 위해 은행 계좌에서 돈을 인출해야 했다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
