INSERT INTO words (headword, meaning_ko, meanings, example_en, example_ko, tags) VALUES ('wonder', '궁금해하다', '[{"pos": "v.", "ko": "궁금해하다"}, {"pos": "n.", "ko": "경이, 놀라움"}]'::jsonb, 'I wonder if it will rain during our school trip tomorrow.', '내일 소풍 때 비가 올지 궁금하다.', NULL) ON CONFLICT (headword, meaning_ko) DO UPDATE SET meanings = EXCLUDED.meanings, example_en = EXCLUDED.example_en, example_ko = EXCLUDED.example_ko, tags = EXCLUDED.tags;
